    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new Department { Id = 1, Name = "Computer Science", Code = "CS", Description = "Explore the theory and practice of computing, from algorithms and data structures to software engineering and artificial intelligence." },
