        };

        _instructors = new List<Instructor>
        {
            new Instructor { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen has over 15 years of experience in software engineering and distributed systems. She previously worked at major tech companies before joining academia and has published extensively on cloud computing and microservices architecture.", Email = "s.chen@university.edu" },
            new Instructor { Id = 2, Name = "Dr. James Martinez", Title = "Associate Professor of Computer Science", Bio = "Dr. Martinez specializes in artificial intelligence and machine learning. His research focuses on natural language processing and its applications in education technology.", Email = "j.martinez@university.edu" },
            new Instructor { Id = 3, Name = "Dr. Emily Watson", Title = "Professor of Mathematics", Bio = "Dr. Watson is an award-winning mathematician whose work in algebraic topology has been recognized internationally. She is passionate about making abstract mathematics accessible to all students.", Email = "e.watson@university.edu" },
            new Instructor { Id = 4, Name = "Dr. Robert Kim", Title = "Associate Professor of Mathematics", Bio = "Dr. Kim brings a unique perspective combining pure mathematics with data science applications. He has consulted for financial institutions on risk modeling and statistical analysis.", Email = "r.kim@university.edu" },
            new Instructor { Id = 5, Name = "Dr. Amanda Foster", Title = "Professor of English", Bio = "Dr. Foster is a published novelist and literary critic specializing in contemporary American fiction. She has received multiple teaching awards and mentors aspiring writers through the university's creative writing program.", Email = "a.foster@university.edu" }
        };

        _courses = new List<Course>
        {
            // Computer Science courses
            new Course { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control structures, functions, data structures, and object-oriented programming. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00 AM - 9:50 AM", Location = "Science Building 201", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 1, InstructorName = "Dr. Sarah Chen", IsFeatured = true, MaxEnrollment = 40, CurrentEnrollment = 32 },
            new Course { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study fundamental data structures including arrays, linked lists, trees, graphs, and hash tables. Analyze algorithm efficiency using Big-O notation and explore sorting, searching, and graph algorithms.", Credits = 4, Schedule = "Tue/Thu 10:30 AM - 12:00 PM", Location = "Science Building 305", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 1, InstructorName = "Dr. Sarah Chen", IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 28 },
            new Course { Id = 3, Code = "CS 310", Title = "Artificial Intelligence", Description = "Explore the principles and techniques of artificial intelligence including search algorithms, knowledge representation, machine learning, and neural networks. Includes hands-on projects with real-world datasets.", Credits = 3, Schedule = "Mon/Wed 2:00 PM - 3:30 PM", Location = "Tech Center 110", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 2, InstructorName = "Dr. James Martinez", IsFeatured = true, MaxEnrollment = 30, CurrentEnrollment = 27 },
            new Course { Id = 4, Code = "CS 450", Title = "Software Engineering", Description = "Learn modern software development practices including agile methodologies, version control, testing, continuous integration, and deployment. Work in teams to build a full-stack web application.", Credits = 4, Schedule = "Tue/Thu 1:00 PM - 2:30 PM", Location = "Tech Center 205", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 2, InstructorName = "Dr. James Martinez", IsFeatured = false, MaxEnrollment = 25, CurrentEnrollment = 20 },

            // Mathematics courses
            new Course { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Introduction to differential calculus covering limits, continuity, derivatives, and their applications. Includes related rates, optimization problems, and curve sketching.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00 AM - 10:50 AM", Location = "Math Hall 101", DepartmentId = 2, DepartmentName = "Mathematics", InstructorId = 3, InstructorName = "Dr. Emily Watson", IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 38 },
            new Course { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Study vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications to computer graphics, data science, and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00 AM - 10:30 AM", Location = "Math Hall 203", DepartmentId = 2, DepartmentName = "Mathematics", InstructorId = 3, InstructorName = "Dr. Emily Watson", IsFeatured = false, MaxEnrollment = 35, CurrentEnrollment = 30 },
            new Course { Id = 7, Code = "MATH 301", Title = "Probability and Statistics", Description = "Cover probability theory, random variables, distributions, hypothesis testing, confidence intervals, and regression analysis. Emphasizes real-world applications and data interpretation.", Credits = 3, Schedule = "Mon/Wed 11:00 AM - 12:30 PM", Location = "Math Hall 105", DepartmentId = 2, DepartmentName = "Mathematics", InstructorId = 4, InstructorName = "Dr. Robert Kim", IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 35 },

            // English courses
            new Course { Id = 8, Code = "ENG 101", Title = "College Writing", Description = "Develop essential academic writing skills through essay composition, research methods, and rhetorical analysis. Focus on clarity, argumentation, and proper citation practices.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00 AM - 11:50 AM", Location = "Humanities 302", DepartmentId = 3, DepartmentName = "English", InstructorId = 5, InstructorName = "Dr. Amanda Foster", IsFeatured = false, MaxEnrollment = 25, CurrentEnrollment = 22 },
            new Course { Id = 9, Code = "ENG 220", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present. Examine works by diverse authors and explore themes of identity, freedom, and the American experience.", Credits = 3, Schedule = "Tue/Thu 2:00 PM - 3:30 PM", Location = "Humanities 210", DepartmentId = 3, DepartmentName = "English", InstructorId = 5, InstructorName = "Dr. Amanda Foster", IsFeatured = true, MaxEnrollment = 30, CurrentEnrollment = 18 },
            new Course { Id = 10, Code = "ENG 350", Title = "Creative Writing Workshop", Description = "Workshop-based course focusing on fiction and poetry writing. Students will produce original works, participate in peer review, and study craft elements through reading published authors.", Credits = 3, Schedule = "Wed 3:00 PM - 5:30 PM", Location = "Humanities 115", DepartmentId = 3, DepartmentName = "English", InstructorId = 5, InstructorName = "Dr. Amanda Foster", IsFeatured = false, MaxEnrollment = 15, CurrentEnrollment = 12 }
        };
    }

    public List<Department> GetDepartments() => _departments.ToList();

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses.ToList();

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId, int? credits)
    {
        var results = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            results = results.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            results = results.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (credits.HasValue && credits.Value > 0)
        {
            results = results.Where(c => c.Credits == credits.Value);
        }

        return results.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public Instructor? GetInstructor(int instructorId) =>
        _instructors.FirstOrDefault(i => i.Id == instructorId);

    public bool SubmitEnrollment(EnrollmentRequest request)
    {
        var course = _courses.FirstOrDefault(c => c.Id == request.CourseId);
        if (course == null || course.CurrentEnrollment >= course.MaxEnrollment)
            return false;

        course.CurrentEnrollment++;
        return true;
    }
}

