.site-wrapper {
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

.site-header {
    background-color: #1a2744;
    color: white;
    padding: 0 1.5rem;
    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
    position: sticky;
    top: 0;
    z-index: 100;
}

.header-content {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 60px;
}

.site-brand {
    color: white;
    font-size: 1.25rem;
    font-weight: 700;
    text-decoration: none;
}

.site-brand:hover {
    color: #c8d6e5;
}

.site-nav {
    display: flex;
    gap: 0.25rem;
}

.site-nav ::deep .nav-link {
    color: #c8d6e5;
    padding: 0.5rem 1rem;
    border-radius: 6px;
    text-decoration: none;
    font-weight: 500;
    transition: background-color 0.2s;
}

.site-nav ::deep .nav-link:hover {
    background-color: rgba(255,255,255,0.1);
    color: white;
}

.site-nav ::deep .nav-link.active {
    background-color: rgba(255,255,255,0.15);
    color: white;
}

.site-main {
    flex: 1;
}

.site-footer {
    background-color: #1a2744;
    color: #8899aa;
    text-align: center;
    padding: 1.25rem;
    font-size: 0.875rem;
}

.site-footer p {
    margin: 0;
}

#blazor-error-ui {
    color-scheme: light only;
