@page "/courses"
@rendermode InteractiveServer
@inject ICatalogService CatalogService

<PageTitle>Courses - University Course Catalog</PageTitle>

<div class="container py-4">
    <h1 class="section-title">Course Catalog</h1>

    <div class="filters-bar">
        <input type="text" class="form-control" placeholder="Search courses..."
               @bind="searchTerm" @bind:event="oninput" />

        <select class="form-select" @bind="selectedDepartment">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>

        <select class="form-select" @bind="selectedCredits">
            <option value="0">Any Credits</option>
            <option value="3">3 Credits</option>
            <option value="4">4 Credits</option>
        </select>
    </div>

    <div class="course-grid">
        @foreach (var course in filteredCourses)
        {
            <UniversityCourseCatalog.Components.Shared.CourseCard Course="course" />
        }
    </div>

    @if (!filteredCourses.Any())
    {
        <div class="no-results">
            <p>No courses found matching your criteria.</p>
        </div>
    }
</div>

@code {
    private string? searchTerm;
    private int selectedDepartment;
    private int selectedCredits;
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        FilterCourses();
    }

    protected override void OnParametersSet()
    {
        FilterCourses();
    }

    private void FilterCourses()
    {
        filteredCourses = CatalogService.SearchCourses(
            searchTerm,
            selectedDepartment > 0 ? selectedDepartment : null,
            selectedCredits > 0 ? selectedCredits : null);
    }
}

@page "/courses/{Id:int}"
@inject ICatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course") - University Course Catalog</PageTitle>

@if (course == null)
{
    <div class="container py-4">
        <h1>Course Not Found</h1>
        <p>The requested course could not be found.</p>
        <a href="/courses">← Back to Courses</a>
    </div>
}
else
{
    <div class="container py-4">
        <a href="/courses" class="back-link">← Back to Courses</a>

        <div class="course-detail">
            <div class="detail-header">
                <span class="course-code-badge">@course.Code</span>
                <h1>@course.Title</h1>
                <p class="detail-meta">
                    <span>📚 @course.DepartmentName</span>
                    <span>🎓 @course.Credits Credits</span>
                    <span>👥 @course.CurrentEnrollment / @course.MaxEnrollment enrolled</span>
                </p>
            </div>

            <div class="detail-body">
                <div class="detail-section">
                    <h2>Description</h2>
                    <p>@course.Description</p>
                </div>

                <div class="detail-section">
                    <h2>Schedule &amp; Location</h2>
                    <p><strong>Schedule:</strong> @course.Schedule</p>
                    <p><strong>Location:</strong> @course.Location</p>
                </div>

                <div class="detail-section">
                    <h2>Instructor</h2>
                    @if (instructor != null)
                    {
                        <div class="instructor-card">
                            <h3>@instructor.Name</h3>
                            <p class="instructor-title">@instructor.Title</p>
                            <p>@instructor.Bio</p>
                            <p><strong>Email:</strong> <a href="mailto:@instructor.Email">@instructor.Email</a></p>
                        </div>
                    }
                </div>
            </div>

            <div class="detail-actions">
                @if (course.CurrentEnrollment < course.MaxEnrollment)
                {
                    <a href="/enroll?courseId=@course.Id" class="btn btn-primary btn-lg">Enroll in This Course</a>
                }
                else
                {
                    <span class="btn btn-secondary btn-lg disabled">Course Full</span>
                }
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;
    private Instructor? instructor;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
        if (course != null)
        {
            instructor = CatalogService.GetInstructor(course.InstructorId);
        }
    }
}

@page "/enroll"
@inject ICatalogService CatalogService

<PageTitle>Enroll - University Course Catalog</PageTitle>

<div class="container py-4">
    <h1 class="section-title">Course Enrollment</h1>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4>✅ Enrollment Successful!</h4>
            <p>Thank you, <strong>@Model.StudentName</strong>. You have been enrolled in the selected course.</p>
            <a href="/courses" class="btn btn-primary">Browse More Courses</a>
        </div>
    }
    else
    {
        <div class="enrollment-form-wrapper">
            <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                <AntiforgeryToken />
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger" />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
                    <ValidationMessage For="() => Model.StudentName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID (e.g., AB123456)</label>
                    <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" />
                    <ValidationMessage For="() => Model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                        <option value="0">-- Select a course --</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id">@course.Code - @course.Title (@course.Credits cr.)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment</button>
            </EditForm>
        </div>

        @if (enrollmentFailed)
        {
            <div class="alert alert-danger mt-3">
                Enrollment failed. The course may be full or does not exist.
            </div>
        }
    }
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = default!;

    [SupplyParameterFromQuery(Name = "courseId")]
    private int? PreselectedCourseId { get; set; }

    private List<Course> courses = new();
    private bool submitted;
    private bool enrollmentFailed;

    protected override void OnInitialized()
    {
        Model ??= new();
        courses = CatalogService.GetCourses();

        if (PreselectedCourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = PreselectedCourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var result = CatalogService.SubmitEnrollment(Model);
        if (result)
        {
            submitted = true;
            enrollmentFailed = false;
        }
        else
        {
            enrollmentFailed = true;
        }
    }
}

