                <h1>@course.Title</h1>
                <p class="detail-meta">
                    <span>📚 @course.DepartmentName</span>
                    <span>🎓 @course.Credits Credits</span>
                    <span>👥 @course.CurrentEnrollment / @course.MaxEnrollment enrolled</span>
                </p>
            </div>

            <div class="detail-body">
                <div class="detail-section">
                    <h2>Description</h2>
                    <p>@course.Description</p>
