@page "/enroll"
@inject ICatalogService CatalogService

<PageTitle>Enroll - University Course Catalog</PageTitle>

<div class="container py-4">
    <h1 class="section-title">Course Enrollment</h1>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4>✅ Enrollment Successful!</h4>
            <p>Thank you, <strong>@Model.StudentName</strong>. You have been enrolled in the selected course.</p>
            <a href="/courses" class="btn btn-primary">Browse More Courses</a>
        </div>
    }
    else
    {
        <div class="enrollment-form-wrapper">
            <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                <AntiforgeryToken />
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger" />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
                    <ValidationMessage For="() => Model.StudentName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID (e.g., AB123456)</label>
                    <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" />
                    <ValidationMessage For="() => Model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                        <option value="0">-- Select a course --</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id">@course.Code - @course.Title (@course.Credits cr.)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment</button>
            </EditForm>
        </div>

        @if (enrollmentFailed)
        {
            <div class="alert alert-danger mt-3">
                Enrollment failed. The course may be full or does not exist.
            </div>
        }
    }
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = default!;

    [SupplyParameterFromQuery(Name = "courseId")]
    private int? PreselectedCourseId { get; set; }

    private List<Course> courses = new();
    private bool submitted;
    private bool enrollmentFailed;

    protected override void OnInitialized()
    {
        Model ??= new();
        courses = CatalogService.GetCourses();

        if (PreselectedCourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = PreselectedCourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var result = CatalogService.SubmitEnrollment(Model);
        if (result)
        {
            submitted = true;
            enrollmentFailed = false;
        }
        else
        {
            enrollmentFailed = true;
        }
    }
}

