html, body {
    font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
    margin: 0;
    padding: 0;
}

a, .btn-link {
    color: #1a5276;
}

.btn-primary {
    color: #fff;
    background-color: #1a2744;
    border-color: #1a2744;
}

.btn-primary:hover {
    background-color: #2c3e6b;
    border-color: #2c3e6b;
}

.btn:focus, .btn:active:focus, .btn-link.nav-link:focus, .form-control:focus, .form-check-input:focus {
    box-shadow: 0 0 0 0.1rem white, 0 0 0 0.25rem #258cfb;
}

/* Hero */
.hero-section {
    background: linear-gradient(135deg, #1a2744 0%, #2c3e6b 50%, #1a5276 100%);
    color: white;
    padding: 5rem 2rem;
    text-align: center;
}

.hero-content {
    max-width: 700px;
    margin: 0 auto;
}

.hero-content h1 {
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: 1rem;
}

.hero-content p {
    font-size: 1.2rem;
    margin-bottom: 2rem;
    opacity: 0.9;
}

.hero-actions {
    display: flex;
    gap: 1rem;
    justify-content: center;
    flex-wrap: wrap;
}

/* Section */
.section-title {
    font-size: 1.75rem;
    font-weight: 700;
    color: #1a2744;
    margin-bottom: 1.5rem;
    padding-bottom: 0.5rem;
    border-bottom: 3px solid #1a5276;
}

/* Course Grid */
.course-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 1.5rem;
}

/* Course Card */
.course-card {
    background: white;
    border: 1px solid #dee2e6;
    border-radius: 10px;
    padding: 1.5rem;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
    transition: box-shadow 0.2s, transform 0.2s;
    display: flex;
    flex-direction: column;
}

.course-card:hover {
    box-shadow: 0 4px 16px rgba(0,0,0,0.12);
    transform: translateY(-2px);
}

.course-card .card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
    background: none;
    border: none;
    padding: 0;
}

.course-card .course-code {
    background-color: #1a2744;
    color: white;
    padding: 0.25rem 0.75rem;
    border-radius: 4px;
    font-weight: 600;
    font-size: 0.85rem;
}

.course-card .course-credits {
    color: #666;
    font-size: 0.875rem;
}

.course-card .course-title {
    font-size: 1.15rem;
    margin-bottom: 0.5rem;
}

.course-card .course-title a {
    color: #1a2744;
    text-decoration: none;
}

.course-card .course-title a:hover {
    color: #1a5276;
    text-decoration: underline;
}

.course-card .course-meta {
    display: flex;
    gap: 1rem;
    font-size: 0.85rem;
    color: #555;
    margin-bottom: 0.75rem;
    flex-wrap: wrap;
}

.course-card .course-description {
    color: #666;
    font-size: 0.9rem;
    flex: 1;
}

.course-card .card-footer {
