 @page "/courses/{Id:int}"
 @inject ICatalogService CatalogService

 <PageTitle>@(course?.Title ?? "Course") - University Course Catalog</PageTitle>

 @if (course == null)
 {
     <div class="container py-4">
         <h1>Course Not Found</h1>
         <p>The requested course could not be found.</p>
         <a href="/courses">← Back to Courses</a>
     </div>
 }
 else
 {
     <div class="container py-4">
         <a href="/courses" class="back-link">← Back to Courses</a>

         <div class="course-detail">
             <div class="detail-header">
                 <span class="course-code-badge">@course.Code</span>
                 <h1>@course.Title</h1>
                 <p class="detail-meta">
                     <span>📚 @course.DepartmentName</span>
                     <span>🎓 @course.Credits Credits</span>
                     <span>👥 @course.CurrentEnrollment / @course.MaxEnrollment enrolled</span>
                 </p>
             </div>

             <div class="detail-body">
                 <div class="detail-section">
                     <h2>Description</h2>
                     <p>@course.Description</p>
                 </div>

                 <div class="detail-section">
                     <h2>Schedule &amp; Location</h2>
                     <p><strong>Schedule:</strong> @course.Schedule</p>
                     <p><strong>Location:</strong> @course.Location</p>
                 </div>

                 <div class="detail-section">
                     <h2>Instructor</h2>
                     @if (instructor != null)
                     {
                         <div class="instructor-card">
                             <h3>@instructor.Name</h3>
                             <p class="instructor-title">@instructor.Title</p>
                             <p>@instructor.Bio</p>
                             <p><strong>Email:</strong> <a href="mailto:@instructor.Email">@instructor.Email</a></p>
                         </div>
                     }
                 </div>
             </div>

             <div class="detail-actions">
                 @if (course.CurrentEnrollment < course.MaxEnrollment)
                 {
                     <a href="/enroll?courseId=@course.Id" class="btn btn-primary btn-lg">Enroll in This Course</a>
                 }
                 else
                 {
                     <span class="btn btn-secondary btn-lg disabled">Course Full</span>
                 }
             </div>
         </div>
     </div>
 }

 @code {
     [Parameter]
     public int Id { get; set; }

     private Course? course;
     private Instructor? instructor;

     protected override void OnInitialized()
     {
         course = CatalogService.GetCourse(Id);
         if (course != null)
         {
             instructor = CatalogService.GetInstructor(course.InstructorId);
         }
     }
 }

